 "content": "def transform(grid):
    """Extract the shared symbol/color from two panels separated by a line."""
    h, w = len(grid), len(grid[0])
    sep_row = next((r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0), None)
    if sep_row is not None:
        a = {v for row in grid[:sep_row] for v in row if v != 0}
        b = {v for row in grid[sep_row + 1:] for v in row if v != 0}
        color = next(iter(a & b))
        return [[color] * w for _ in range(sep_row)]
    sep_col = next((c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] == 0), None)
    if sep_col is not None:
        left = [row[:sep_col] for row in grid]
        right = [row[sep_col + 1:] for row in grid]
        ca, cb = {v for row in left for v in row}, {v for row in right for v in row}
        common = ca & cb
        # Select the shared color whose incidence pattern matches most closely.
        color = max(common, key=lambda v: sum(left[r][c] == v and right[r][c] == v for r in range(h) for c in range(min(len(left[r]), len(right[r])))))
        return [[color] * len(left[0]) for _ in range(h)]
    raise ValueError('No separator')
